changeSet.sql:
select user_id into @adminUser from users where system_id = 'admin'; select person_attribute_type_id into @healthCenterType from person_attribute_type where uuid = '8d87236c-c2cc-11de-8d13-0010c6dffd0f';
DROP TEMPORARY TABLE IF EXISTS temp_most_common_visit_location; create temporary table temp_most_common_visit_location select location_id from visit where voided = 0 group by location_id order by count(*) desc, location_id asc limit 1;
insert into person_attribute (person_id, value, person_attribute_type_id, creator, date_created, voided, uuid) select p.person_id, tmcvl.location_id, @healthCenterType, @adminUser, now(), 0, uuid() from person p inner join patient pt on pt.patient_id = p.person_id cross join temp_most_common_visit_location tmcvl where p.voided = 0 and not exists ( select 1 from person_attribute pa where pa.person_id = p.person_id and pa.person_attribute_type_id = @healthCenterType and pa.voided = 0 );
